class TestIsNoop:
    def test_zero_action_is_noop(self):
        action = np.array([0, 0, 0, 0, 0, 0, 1.0])
        assert is_noop(action)

    def test_nonzero_action_is_not_noop(self):
        action = np.array([0.1, 0, 0, 0, 0, 0, 1.0])
        assert not is_noop(action)

    def test_gripper_change_is_not_noop(self):
        action = np.array([0, 0, 0, 0, 0, 0, 1.0])
        prev = np.array([0, 0, 0, 0, 0, 0, -1.0])
        assert not is_noop(action, prev)

    def test_same_gripper_zero_motion_is_noop(self):
        action = np.array([0, 0, 0, 0, 0, 0, 1.0])
        prev = np.array([0.1, 0, 0, 0, 0, 0, 1.0])
        assert is_noop(action, prev)


